fn main() {
    let bonus = 5;
    let add_bonus = |score: i32| score + bonus;
    println!("{}", add_bonus(10));

    let mut calls = 0;
    let mut count_call = || calls += 1;
    count_call();
    count_call();
    count_call();
    println!("{calls}");
}
